n=30
g=[[0]*n for _ in range(n)]
# outer 5 frame rows/cols 1..25
for c in range(1,26):
    g[1][c]=5; g[25][c]=5
for r in range(1,26):
    g[r][1]=5; g[r][25]=5
# first inward layer = 2
for c in range(2,25):
    g[2][c]=2; g[24][c]=2
for r in range(3,24):
    g[r][2]=2; g[r][24]=2
# second inward layer = 5
for c in range(3,24):
    g[3][c]=5; g[23][c]=5
for r in range(4,23):
    g[r][3]=5; g[r][23]=5
assert len(g)==30 and all(len(row)==30 for row in g)
import json
print(json.dumps(g,separators=(',',':')))
